with filtered as (select *, initcap(trim(browser)) as browser_title, coalesce(browser, 'unassigned') as browser_filled from sessions where started_at >= to_timestamp('2023-04-30 20:00:00') and customer_id is not null), flagged as (select *, case when started_at - lag(started_at) over (partition by browser order by started_at, id) > interval 90 days then 1 else 0 end as is_new_burst from filtered), sessionized as (select *, sum(is_new_burst) over (partition by browser order by started_at, id rows between unbounded preceding and current row) as session_id from flagged) select country, customer_id, max(started_at) as last_started_at, count(distinct browser) as distinct_browsers, count_if(country = 'DE') as de_events from sessionized group by 1, 2 order by de_events nulls first
